//! Checkpoint 1, behaviour tests: does the library do what SPEC.md says?
//!
//! Run: cargo test --test behaviour
//!
//! All of these must pass, in debug and with `--release`, for the "pass"
//! level in RUBRIC.md. Do not edit this file.

mod common;

use std::error::Error;

use common::within;
use splitpot::{
    AmountError, Cause, Entry, EntryError, Ledger, Overflow, ReadError, Transfer, Unbalanced,
    parse_amount, parse_entry, read_ledger, report, settle,
};

fn owned(pairs: &[(&str, i64)]) -> Vec<(String, i64)> {
    pairs
        .iter()
        .map(|&(name, cents)| (name.to_string(), cents))
        .collect()
}

/// `settle` with a time limit: a planning loop that never ends becomes a
/// failed test instead of a test run that hangs.
fn settle_owned(pairs: &[(&str, i64)]) -> Result<Vec<(String, String, u64)>, Unbalanced> {
    let balances = owned(pairs);
    within(10, "settle", move || {
        settle(&balances).map(|transfers| {
            transfers
                .iter()
                .map(|t| (t.from.to_string(), t.to.to_string(), t.cents))
                .collect()
        })
    })
}

fn transfer(from: &str, to: &str, cents: u64) -> (String, String, u64) {
    (from.to_string(), to.to_string(), cents)
}

// ---------------------------------------------------------------- amounts

#[test]
fn amount_whole_numbers_and_decimals() {
    assert_eq!(parse_amount("0"), Ok(0));
    assert_eq!(parse_amount("7"), Ok(700));
    assert_eq!(
        parse_amount("12.5"),
        Ok(1250),
        "one decimal digit means tenths: 12.5 is 12.50"
    );
    assert_eq!(parse_amount("12.50"), Ok(1250));
    assert_eq!(parse_amount("0.07"), Ok(7));
    assert_eq!(parse_amount("3.00"), Ok(300));
}

#[test]
fn amount_leading_zeros_are_allowed() {
    assert_eq!(parse_amount("007"), Ok(700));
    assert_eq!(parse_amount("00.10"), Ok(10));
    assert_eq!(parse_amount("000000000000000000000000000001.01"), Ok(101));
}

#[test]
fn amount_the_largest_value_is_u64_max_cents() {
    assert_eq!(parse_amount("184467440737095516.15"), Ok(u64::MAX));
    assert_eq!(
        parse_amount("184467440737095516.16"),
        Err(AmountError::TooLarge)
    );
    assert_eq!(
        parse_amount("184467440737095517"),
        Err(AmountError::TooLarge)
    );
    assert_eq!(
        parse_amount("9999999999999999999999999999999999999999"),
        Err(AmountError::TooLarge),
        "more digits than a u64 can hold is TooLarge, not Malformed"
    );
}

#[test]
fn amount_empty_text() {
    assert_eq!(parse_amount(""), Err(AmountError::Empty));
}

#[test]
fn amount_malformed_texts() {
    let bad = [
        " 5", "5 ", "+5", "-5", "5.", ".5", ".", "5.123", "5,00", "1e3", "5.1x", "x", "1_000",
        "0x10", "5..0", "5.0.0", "٣", "5.٣",
    ];
    for text in bad {
        assert_eq!(
            parse_amount(text),
            Err(AmountError::Malformed),
            "{text:?} does not match the grammar DIGITS [ \".\" DIGIT [ DIGIT ] ]"
        );
    }
}

// ---------------------------------------------------------------- entries

#[test]
fn entry_fields() {
    let entry = parse_entry("ana paid 30.00 for ana, ben, cy").unwrap();
    assert_eq!(entry.payer, "ana");
    assert_eq!(entry.cents, 3000);
    assert_eq!(entry.sharers, ["ana", "ben", "cy"]);
}

#[test]
fn entry_white_space_is_flexible() {
    let expected = Entry {
        payer: "ana",
        cents: 500,
        sharers: vec!["ben", "cy"],
    };
    assert_eq!(parse_entry("ana paid 5 for ben,cy").as_ref(), Ok(&expected));
    assert_eq!(
        parse_entry("  ana\tpaid   5  for   ben ,cy  ").as_ref(),
        Ok(&expected)
    );
    assert_eq!(
        parse_entry("ana paid 5 for\tben\t,\tcy").as_ref(),
        Ok(&expected)
    );
}

#[test]
fn entry_names_are_any_text_without_white_space_or_commas() {
    let entry = parse_entry("Zoë paid 1 for 李, o'neil, x#1, paid, for").unwrap();
    assert_eq!(entry.payer, "Zoë");
    assert_eq!(entry.sharers, ["李", "o'neil", "x#1", "paid", "for"]);
    assert_eq!(
        parse_entry("ana paid 1 for Ana").unwrap().sharers,
        ["Ana"],
        "names are compared exactly: ana and Ana are two people"
    );
}

#[test]
fn entry_syntax_errors() {
    let bad = [
        "",
        "   ",
        "ana",
        "ana paid",
        "ana paid 5",
        "ana paid 5 for",
        "ana paid 5 for   ",
        "ana Paid 5 for ben",
        "ana paid 5 FOR ben",
        "ana paid 5 to ben",
        "ana gave 5 for ben",
        "ana paid 5 for ben cy",
        "ana paid 5 for ben,",
        "ana paid 5 for ,ben",
        "ana paid 5 for ben,,cy",
        "a,b paid 5 for ben",
        "ana paid 5 forben",
        "paid 5 for ben",
    ];
    for line in bad {
        assert_eq!(parse_entry(line), Err(EntryError::Syntax), "line {line:?}");
    }
}

#[test]
fn entry_amount_errors_keep_the_reason() {
    assert_eq!(
        parse_entry("ana paid 5.123 for ben"),
        Err(EntryError::Amount(AmountError::Malformed))
    );
    assert_eq!(
        parse_entry("ana paid 184467440737095517 for ben"),
        Err(EntryError::Amount(AmountError::TooLarge))
    );
    assert_eq!(
        parse_entry("ana paid for ben"),
        Err(EntryError::Amount(AmountError::Malformed)),
        "the third word is always read as the amount; here it is the word `for`"
    );
}

#[test]
fn entry_duplicate_sharer() {
    assert_eq!(
        parse_entry("ana paid 5 for ben, cy, ben"),
        Err(EntryError::DuplicateSharer)
    );
    assert_eq!(
        parse_entry("ana paid 5 for ana, ana"),
        Err(EntryError::DuplicateSharer)
    );
}

#[test]
fn entry_the_first_problem_from_the_left_decides() {
    assert_eq!(
        parse_entry("ana paid 1.2.3 to ben,,"),
        Err(EntryError::Amount(AmountError::Malformed)),
        "the amount comes before the word `for` and before the list"
    );
    assert_eq!(
        parse_entry("ana paid 5 for ben, ben, , cy"),
        Err(EntryError::DuplicateSharer)
    );
    assert_eq!(
        parse_entry("ana paid 5 for ben, , ben"),
        Err(EntryError::Syntax)
    );
    assert_eq!(
        parse_entry("ana gave 1.2.3 for ben"),
        Err(EntryError::Syntax)
    );
}

// ----------------------------------------------------------------- ledger

#[test]
fn ledger_starts_empty() {
    let ledger = Ledger::new();
    assert_eq!(ledger.balance("ana"), None);
    assert!(ledger.names().is_empty());
    assert!(Ledger::default().into_balances().is_empty());
}

#[test]
fn ledger_one_entry() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 30 for ana, ben, cy").unwrap())
        .unwrap();
    assert_eq!(
        ledger.balance("ana"),
        Some(2000),
        "ana paid 3000 and owes 1000 of it"
    );
    assert_eq!(ledger.balance("ben"), Some(-1000));
    assert_eq!(ledger.balance("cy"), Some(-1000));
    assert_eq!(ledger.balance("dee"), None);
}

#[test]
fn ledger_payer_who_does_not_share() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 9 for ben, cy").unwrap())
        .unwrap();
    assert_eq!(ledger.balance("ana"), Some(900));
    assert_eq!(ledger.balance("ben"), Some(-450));
    assert_eq!(ledger.balance("cy"), Some(-450));
}

#[test]
fn ledger_left_over_cents_go_to_the_first_sharers() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("x paid 0.05 for c, a, b").unwrap())
        .unwrap();
    assert_eq!(
        ledger.balance("c"),
        Some(-2),
        "c is first in the list and takes one extra cent"
    );
    assert_eq!(
        ledger.balance("a"),
        Some(-2),
        "a is second in the list and takes the other"
    );
    assert_eq!(ledger.balance("b"), Some(-1));
    assert_eq!(ledger.balance("x"), Some(5));

    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 10 for ana, ben, cy").unwrap())
        .unwrap();
    assert_eq!(ledger.balance("ana"), Some(1000 - 334));
    assert_eq!(ledger.balance("ben"), Some(-333));
    assert_eq!(ledger.balance("cy"), Some(-333));
}

#[test]
fn ledger_entries_add_up() {
    let mut ledger = Ledger::new();
    for line in [
        "ana paid 30 for ana, ben, cy",
        "ben paid 12.50 for ana, ben",
        "cy paid 7 for ben",
        "ana paid 0.01 for cy, ben",
    ] {
        ledger.add(&parse_entry(line).unwrap()).unwrap();
    }
    assert_eq!(ledger.balance("ana"), Some(2000 - 625 + 1));
    assert_eq!(ledger.balance("ben"), Some(-1000 + 625 - 700));
    assert_eq!(ledger.balance("cy"), Some(-1000 + 700 - 1));
}

#[test]
fn ledger_names_and_balances_are_sorted_by_name() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("zed paid 2 for mo, Zed").unwrap())
        .unwrap();
    ledger
        .add(&parse_entry("abe paid 1 for zed").unwrap())
        .unwrap();
    assert_eq!(
        ledger.names(),
        ["Zed", "abe", "mo", "zed"],
        "the order is the order of `str`: byte by byte, so Z comes before a"
    );
    assert_eq!(
        ledger.into_balances(),
        owned(&[("Zed", -100), ("abe", 100), ("mo", -100), ("zed", 100)])
    );
}

#[test]
fn ledger_zero_amount_still_introduces_the_people() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 0 for ben").unwrap())
        .unwrap();
    assert_eq!(ledger.into_balances(), owned(&[("ana", 0), ("ben", 0)]));
}

#[test]
fn ledger_entry_without_sharers_changes_nothing() {
    let mut ledger = Ledger::new();
    let nobody = Entry {
        payer: "ana",
        cents: 500,
        sharers: Vec::new(),
    };
    assert_eq!(ledger.add(&nobody), Ok(()));
    assert!(
        ledger.names().is_empty(),
        "an entry that nobody shares must not credit the payer: the balances would no longer add up to zero"
    );
}

#[test]
fn ledger_balances_always_add_up_to_zero() {
    let mut ledger = Ledger::new();
    let people = ["a", "b", "c", "d", "e", "f", "g"];
    // A fixed pseudo-random sequence of entries.
    let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
    let mut next = |limit: u64| {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (state >> 33) % limit
    };
    for _ in 0..500 {
        let payer = people[next(7) as usize];
        let first = next(7) as usize;
        let count = 1 + next(7) as usize;
        let sharers: Vec<&str> = (0..count).map(|i| people[(first + i) % 7]).collect();
        let entry = Entry {
            payer,
            cents: next(100_000),
            sharers,
        };
        ledger.add(&entry).unwrap();
    }
    let sum: i64 = ledger.into_balances().iter().map(|(_, cents)| cents).sum();
    assert_eq!(
        sum, 0,
        "every cent that one person is owed, another person owes"
    );
}

#[test]
fn ledger_overflow_is_reported() {
    let mut ledger = Ledger::new();
    // i64::MAX cents.
    let huge = parse_entry("ana paid 92233720368547758.07 for ben").unwrap();
    assert_eq!(ledger.add(&huge), Ok(()));
    assert_eq!(ledger.balance("ana"), Some(i64::MAX));
    assert_eq!(ledger.balance("ben"), Some(-i64::MAX));
    assert_eq!(ledger.add(&huge), Err(Overflow));
    assert_eq!(
        ledger.balance("ana"),
        Some(i64::MAX),
        "a failed `add` changes nothing"
    );
    assert_eq!(
        ledger.balance("ben"),
        Some(-i64::MAX),
        "a failed `add` changes nothing"
    );
}

// ------------------------------------------------------------ whole files

const TRIP: &str = "\
# Weekend trip
ana paid 30.00 for ana, ben, cy

   # fuel
ben paid 12.50 for ana, ben
cy paid 7 for ben
";

#[test]
fn file_with_comments_and_blank_lines() {
    let ledger = read_ledger(TRIP).unwrap();
    assert_eq!(
        ledger.into_balances(),
        owned(&[("ana", 1375), ("ben", -1075), ("cy", -300)])
    );
}

#[test]
fn file_empty_and_comment_only() {
    assert!(read_ledger("").unwrap().names().is_empty());
    assert!(
        read_ledger("\n\n  \n# nothing\n")
            .unwrap()
            .names()
            .is_empty()
    );
}

#[test]
fn file_windows_line_endings() {
    let ledger = read_ledger("ana paid 1 for ben\r\n\r\n# x\r\nben paid 1 for ana\r\n").unwrap();
    assert_eq!(ledger.into_balances(), owned(&[("ana", 0), ("ben", 0)]));
}

#[test]
fn file_errors_carry_the_line_number() {
    let text = "# header\n\nana paid 5 for ben\nben paid 5.555 for ana\nthis line is never read";
    assert_eq!(
        read_ledger(text).unwrap_err(),
        ReadError {
            line: 4,
            cause: Cause::Entry(EntryError::Amount(AmountError::Malformed))
        },
        "lines are counted from 1, and blank and comment lines count too"
    );
    assert_eq!(
        read_ledger("ana owes ben 5").unwrap_err(),
        ReadError {
            line: 1,
            cause: Cause::Entry(EntryError::Syntax)
        }
    );
    assert_eq!(
        read_ledger("a paid 1 for b\n\n\na paid 1 for b, b\n").unwrap_err(),
        ReadError {
            line: 4,
            cause: Cause::Entry(EntryError::DuplicateSharer)
        }
    );
}

#[test]
fn file_overflow_carries_the_line_number() {
    let text = "ana paid 92233720368547758.07 for ben\n# again\nana paid 0.01 for ben\n";
    assert_eq!(
        read_ledger(text).unwrap_err(),
        ReadError {
            line: 3,
            cause: Cause::Overflow
        }
    );
}

// ----------------------------------------------------------------- errors

#[test]
fn error_messages() {
    assert_eq!(AmountError::Empty.to_string(), "amount is empty");
    assert_eq!(
        AmountError::Malformed.to_string(),
        "amount is not a number with at most two decimal places"
    );
    assert_eq!(AmountError::TooLarge.to_string(), "amount is too large");
    assert_eq!(
        EntryError::Syntax.to_string(),
        "expected: <payer> paid <amount> for <name>, <name>, ..."
    );
    assert_eq!(
        EntryError::Amount(AmountError::Empty).to_string(),
        "invalid amount"
    );
    assert_eq!(
        EntryError::DuplicateSharer.to_string(),
        "a name appears twice after `for`"
    );
    assert_eq!(Overflow.to_string(), "balance out of range");
    assert_eq!(Unbalanced.to_string(), "balances do not add up to zero");
    assert_eq!(
        ReadError {
            line: 12,
            cause: Cause::Entry(EntryError::Syntax)
        }
        .to_string(),
        "line 12: invalid entry"
    );
    assert_eq!(
        ReadError {
            line: 3,
            cause: Cause::Overflow
        }
        .to_string(),
        "line 3: balance out of range"
    );
}

#[test]
fn error_sources_form_a_chain() {
    let error = ReadError {
        line: 2,
        cause: Cause::Entry(EntryError::Amount(AmountError::TooLarge)),
    };
    let entry = error
        .source()
        .expect("a ReadError caused by an entry has that EntryError as its source");
    assert_eq!(
        entry.downcast_ref::<EntryError>(),
        Some(&EntryError::Amount(AmountError::TooLarge))
    );
    let amount = entry
        .source()
        .expect("EntryError::Amount has the AmountError as its source");
    assert_eq!(
        amount.downcast_ref::<AmountError>(),
        Some(&AmountError::TooLarge)
    );
    assert!(
        amount.source().is_none(),
        "an AmountError is the start of the chain"
    );

    assert!(EntryError::Syntax.source().is_none());
    assert!(EntryError::DuplicateSharer.source().is_none());
    assert!(
        ReadError {
            line: 1,
            cause: Cause::Overflow
        }
        .source()
        .is_none()
    );
    assert!(Overflow.source().is_none());
    assert!(Unbalanced.source().is_none());
}

#[test]
fn error_conversion_from_amount_error() {
    assert_eq!(
        EntryError::from(AmountError::Empty),
        EntryError::Amount(AmountError::Empty)
    );
}

#[test]
fn report_joins_the_chain() {
    let error = read_ledger("\nana paid 1.999 for ben").unwrap_err();
    assert_eq!(
        report(&error),
        "line 2: invalid entry: invalid amount: amount is not a number with at most two decimal places"
    );
    assert_eq!(report(&AmountError::Empty), "amount is empty");
    assert_eq!(report(&EntryError::Syntax), EntryError::Syntax.to_string());

    // `report` works for any error, not only for the ones of this crate.
    let foreign = "x".parse::<u8>().unwrap_err();
    assert_eq!(report(&foreign), foreign.to_string());
}

#[test]
fn errors_work_with_question_mark_and_boxed_errors() {
    fn run(text: &str) -> Result<usize, Box<dyn Error + Send + Sync + 'static>> {
        let ledger = read_ledger(text)?;
        let balances = ledger.into_balances();
        let transfers = settle(&balances)?;
        parse_amount("1")?;
        parse_entry("a paid 1 for b")?;
        Ok(transfers.len())
    }
    assert_eq!(run(TRIP).unwrap(), 2);
    let error = run("nonsense").unwrap_err();
    assert_eq!(error.to_string(), "line 1: invalid entry");
    assert!(
        error.downcast_ref::<ReadError>().is_some(),
        "the boxed error is still a ReadError"
    );
}

// --------------------------------------------------------------- settling

#[test]
fn settle_nothing_to_do() {
    assert_eq!(settle_owned(&[]), Ok(vec![]));
    assert_eq!(settle_owned(&[("ana", 0), ("ben", 0)]), Ok(vec![]));
}

#[test]
fn settle_two_people() {
    assert_eq!(
        settle_owned(&[("ana", 500), ("ben", -500)]),
        Ok(vec![transfer("ben", "ana", 500)])
    );
}

#[test]
fn settle_the_trip() {
    let balances = read_ledger(TRIP).unwrap().into_balances();
    let plan = settle(&balances).unwrap();
    assert_eq!(
        plan,
        [
            Transfer {
                from: "ben",
                to: "ana",
                cents: 1075
            },
            Transfer {
                from: "cy",
                to: "ana",
                cents: 300
            },
        ]
    );
}

#[test]
fn settle_largest_debt_pays_largest_credit_first() {
    assert_eq!(
        settle_owned(&[("a", 700), ("b", -400), ("c", 300), ("d", -600)]),
        Ok(vec![
            transfer("d", "a", 600),
            transfer("b", "c", 300),
            transfer("b", "a", 100),
        ]),
        "after the first transfer a is owed 100 and c is owed 300, so b pays c first"
    );
}

#[test]
fn settle_ties_go_to_the_earlier_position() {
    assert_eq!(
        settle_owned(&[("z", -5), ("m", 5), ("a", -5), ("k", 5)]),
        Ok(vec![transfer("z", "m", 5), transfer("a", "k", 5)]),
        "among equal balances the one that comes first in the slice is used, whatever its name"
    );
}

#[test]
fn settle_unbalanced_input() {
    assert_eq!(settle_owned(&[("ana", 1)]), Err(Unbalanced));
    assert_eq!(
        settle_owned(&[("ana", 500), ("ben", -499)]),
        Err(Unbalanced)
    );
    assert_eq!(settle_owned(&[("ana", -3), ("ben", -3)]), Err(Unbalanced));
}

#[test]
fn settle_plan_brings_every_balance_to_zero() {
    let pairs = [
        ("a", 1234),
        ("b", -40),
        ("c", -2000),
        ("d", 5),
        ("e", 801),
        ("f", 0),
        ("g", -1),
        ("h", 1),
    ];
    let plan = settle_owned(&pairs).unwrap();
    assert!(
        plan.len() < pairs.len(),
        "n people never need more than n - 1 transfers"
    );
    let mut left: Vec<(String, i64)> = owned(&pairs);
    for (from, to, cents) in &plan {
        assert!(*cents > 0, "a transfer of zero cents is not a transfer");
        assert_ne!(from, to, "nobody pays themselves");
        for (name, balance) in &mut left {
            if name == from {
                *balance += *cents as i64;
            }
            if name == to {
                *balance -= *cents as i64;
            }
        }
    }
    assert!(
        left.iter().all(|(_, balance)| *balance == 0),
        "open balances after the plan: {left:?}"
    );
}
